sp_widget.client_script:
api.controller = function($window) {

    var c = this;


    var LAST_OPENED_KEY =
        "campus_connect_notifications_last_opened";


    var DELETED_KEY =
        "campus_connect_notifications_deleted";


    /*
     * Get deleted notification IDs
     */

    function getDeletedNotifications() {

        try {

            return JSON.parse(
                $window.localStorage.getItem(
                    DELETED_KEY
                ) || "[]"
            );

        } catch (e) {

            return [];

        }

    }


    /*
     * Save deleted notification IDs
     */

    function saveDeletedNotifications(list) {

        $window.localStorage.setItem(
            DELETED_KEY,
            JSON.stringify(list)
        );

    }


    /*
     * Remove deleted notifications
     * from current page
     */

    function removeDeletedNotifications() {

        var deleted =
            getDeletedNotifications();


        if (
            !c.data ||
            !c.data.notifications
        ) {

            return;

        }


        c.data.notifications =
            c.data.notifications.filter(
                function(notification) {

                    return deleted.indexOf(
                        notification.notification_id
                    ) === -1;

                }
            );

    }


    /*
     * Delete individual notification
     */

    c.deleteNotification =
        function(notification) {

            if (
                !notification ||
                !notification.notification_id
            ) {

                return;

            }


            var deleted =
                getDeletedNotifications();


            if (
                deleted.indexOf(
                    notification.notification_id
                ) === -1
            ) {

                deleted.push(
                    notification.notification_id
                );

            }


            saveDeletedNotifications(
                deleted
            );


            /*
             * Remove immediately
             */

            var index =
                c.data.notifications.indexOf(
                    notification
                );


            if (index !== -1) {

                c.data.notifications.splice(
                    index,
                    1
                );

            }


            /*
             * Update count
             */

            c.data.unread_count =
                c.data.notifications.length;

        };


    /*
     * Mark notifications as opened
     */

    function markNotificationsOpened() {

        $window.localStorage.setItem(
            LAST_OPENED_KEY,
            new Date().toISOString()
        );


        /*
         * Badge becomes zero
         */

        c.data.unread_count = 0;

    }


    /*
     * Initialize
     */

    removeDeletedNotifications();

    markNotificationsOpened();

};

sp_widget.css:
/* =========================================================
   NOTIFICATIONS PAGE LAYOUT
   ========================================================= */

.cc-notifications-layout {

    width: 100%;
    min-height: 100vh;

    display: flex;

    background: transparent;

}


/* =========================================================
   SIDEBAR AREA
   ========================================================= */

.cc-notifications-sidebar {

    width: 208px;
    min-width: 208px;

    min-height: 100vh;

    position: relative;

}


/* =========================================================
   NOTIFICATIONS CONTENT AREA
   ========================================================= */

.cc-notifications-content {

    flex: 1;

    min-width: 0;
    min-height: 100vh;

}


/* =========================================================
   NOTIFICATIONS PAGE
   ========================================================= */

.cc-notifications-page {

    min-height: 100vh;

    background: #f5f9ff;

    padding: 30px;

    font-family:
        "Segoe UI",
        Arial,
        sans-serif;

}


/* =========================================================
   HEADER
   ========================================================= */

.notification-header {

    background: #ffffff;

    border: 1px solid #dbeafe;

    border-radius: 14px;

    padding: 24px 28px;

    margin-bottom: 22px;

    display: flex;

    align-items: center;

    justify-content: space-between;

    box-shadow:
        0 4px 15px
        rgba(37, 99, 235, 0.08);

}


.notification-header h2 {

    margin: 0;

    color: #0f3d91;

    font-size: 28px;

    font-weight: 700;

}


.notification-header p {

    margin: 7px 0 0;

    color: #64748b;

    font-size: 14px;

}


/* =========================================================
   UNREAD COUNT
   ========================================================= */

.notification-count {

    min-width: 42px;

    height: 42px;

    display: flex;

    align-items: center;

    justify-content: center;

    background: #2563eb;

    color: #ffffff;

    border-radius: 50%;

    font-size: 17px;

    font-weight: 700;

    box-shadow:
        0 4px 10px
        rgba(37, 99, 235, 0.25);

}


/* =========================================================
   NOTIFICATION LIST
   ========================================================= */

.notification-list {

    display: flex;

    flex-direction: column;

    gap: 14px;

}


/* =========================================================
   NOTIFICATION CARD
   ========================================================= */

.notification-card {

    background: #ffffff;

    border: 1px solid #dbeafe;

    border-left: 5px solid #2563eb;

    border-radius: 12px;

    padding: 20px;

    display: flex;

    align-items: flex-start;

    gap: 18px;

    position: relative;

    box-shadow:
        0 3px 12px
        rgba(37, 99, 235, 0.06);

    transition:
        all 0.2s ease;

}


.notification-card:hover {

    transform: translateY(-2px);

    box-shadow:
        0 8px 20px
        rgba(37, 99, 235, 0.12);

}


/* =========================================================
   ICON
   ========================================================= */

.notification-icon {

    width: 48px;

    height: 48px;

    flex-shrink: 0;

    display: flex;

    align-items: center;

    justify-content: center;

    background: #eff6ff;

    border-radius: 12px;

    font-size: 24px;

}


/* =========================================================
   CONTENT
   ========================================================= */

.notification-content {

    flex: 1;

}


.notification-content h4 {

    margin: 0 0 7px;

    color: #0f3d91;

    font-size: 17px;

    font-weight: 700;

}


.notification-content p {

    margin: 0 0 8px;

    color: #475569;

    font-size: 14px;

    line-height: 1.5;

}


.notification-details {

    color: #1d4ed8;

    font-size: 13px;

    margin-bottom: 7px;

}


.notification-content small {

    color: #94a3b8;

    font-size: 12px;

}


/* =========================================================
   STATUS
   ========================================================= */

.notification-status {

    flex-shrink: 0;

}


.notification-status span {

    display: inline-block;

    padding: 6px 10px;

    border-radius: 20px;

    font-size: 11px;

    font-weight: 600;

}


.status-request {

    background: #dbeafe;

    color: #1d4ed8;

}


.status-response {

    background: #e0f2fe;

    color: #0369a1;

}


.status-deadline {

    background: #fef3c7;

    color: #92400e;

}


/* =========================================================
   DELETE BUTTON
   ========================================================= */

.notification-delete {

    width: 30px;

    height: 30px;

    border: none;

    border-radius: 50%;

    background: transparent;

    color: #94a3b8;

    font-size: 22px;

    line-height: 1;

    cursor: pointer;

    display: flex;

    align-items: center;

    justify-content: center;

    transition:
        background 0.2s ease,
        color 0.2s ease;

}


.notification-delete:hover {

    background: #eff6ff;

    color: #2563eb;

}


/* =========================================================
   EMPTY STATE
   ========================================================= */

.empty-notifications {

    background: #ffffff;

    border: 1px solid #dbeafe;

    border-radius: 14px;

    padding: 60px 30px;

    text-align: center;

    box-shadow:
        0 4px 15px
        rgba(37, 99, 235, 0.06);

}


.empty-icon {

    font-size: 45px;

    margin-bottom: 15px;

}


.empty-notifications h3 {

    color: #0f3d91;

    margin: 0 0 8px;

}


.empty-notifications p {

    color: #64748b;

    margin: 0;

}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 900px) {

    .cc-notifications-layout {

        display: block;

    }


    .cc-notifications-sidebar {

        width: 100%;

        min-width: 100%;

        min-height: auto;

    }


    .cc-notifications-content {

        width: 100%;

    }

}


@media (max-width: 768px) {

    .cc-notifications-page {

        padding: 15px;

    }


    .notification-header {

        padding: 18px;

    }


    .notification-header h2 {

        font-size: 22px;

    }


    .notification-card {

        padding: 15px;

        gap: 12px;

    }


    .notification-status {

        display: none;

    }

}

sp_widget.script:
(function() { 

    /* 
     * Load existing Campus Connect Sidebar 
     */ 
    data.sidebar_widget = 
        $sp.getWidget( 
            "campus_connect_sidebar" 
        ); 

    data.notifications = []; 
    data.unread_count = 0; 

    var currentUser = gs.getUserID(); 


    /* 
     * ========================================== 
     * 1. TEAM JOIN REQUEST
     * ========================================== 
     * 
     * The receiver gets a notification when
     * someone sends a request to their team.
     *
     * Team.team_lead is Student Profile.
     * Student Profile.student is sys_user.
     */ 

    var teamRequests = new GlideRecord( 
        'x_snc_campus_con_0_team_members' 
    ); 

    teamRequests.addQuery( 
        'join_status', 
        'requested' 
    ); 

    teamRequests.addQuery( 
        'team.team_lead.student', 
        currentUser 
    ); 

    teamRequests.orderByDesc( 
        'sys_created_on' 
    ); 

    teamRequests.query(); 


    while (teamRequests.next()) { 

        var requestTeamName = ''; 

        if (!teamRequests.team.nil()) { 

            requestTeamName = 
                teamRequests.team.getDisplayValue(); 

        } 

        data.notifications.push({ 

            type: 'team_request', 

            icon: '👥', 

            title: 'Team Join Request', 

            message: 
                'A student has requested to join your team.', 

            details: requestTeamName, 

            created_on: 
                teamRequests.getDisplayValue( 
                    'sys_created_on' 
                ), 

            record_id: 
                teamRequests.getUniqueValue(), 

            notification_id: 
                'team_request_' + 
                teamRequests.getUniqueValue(), 

            unread: true 

        }); 

    } 


    /* 
     * ========================================== 
     * 2. TEAM REQUEST ACCEPTED / REJECTED
     * ========================================== 
     *
     * IMPORTANT:
     *
     * The person who sent the request is the
     * Team Lead.
     *
     * Team Lead -> Student Profile -> Student
     *
     * Therefore the notification must be shown
     * to team.team_lead.student.
     */ 

    var teamResponses = new GlideRecord( 
        'x_snc_campus_con_0_team_members' 
    ); 


    /* 
     * The logged-in user must be the
     * ORIGINAL REQUESTER / TEAM LEAD.
     */ 

    teamResponses.addQuery( 
        'team.team_lead.student', 
        currentUser 
    ); 


    /* 
     * Only processed requests.
     */ 

    teamResponses.addQuery( 
        'join_status', 
        'IN', 
        'accepted,rejected' 
    ); 

    teamResponses.orderByDesc( 
        'sys_updated_on' 
    ); 

    teamResponses.query(); 


    while (teamResponses.next()) { 

        var status = 
            String( 
                teamResponses.getValue( 
                    'join_status' 
                ) || '' 
            ).trim().toLowerCase(); 


        var responseIcon = '❌'; 

        var responseMessage = 
            'Your team request has been rejected.'; 


        /* 
         * ACCEPTED
         */ 

        if (status === 'accepted') { 

            responseIcon = '✅'; 

            responseMessage = 
                'Your team request has been accepted.'; 

        } 


        var responseTeamName = ''; 

        if (!teamResponses.team.nil()) { 

            responseTeamName = 
                teamResponses.team.getDisplayValue(); 

        } 


        data.notifications.push({ 

            type: 'team_response', 

            icon: responseIcon, 

            title: 'Team Request Update', 

            message: responseMessage, 

            details: responseTeamName, 

            created_on: 
                teamResponses.getDisplayValue( 
                    'sys_updated_on' 
                ), 

            record_id: 
                teamResponses.getUniqueValue(), 

            notification_id: 
                'team_response_' + 
                teamResponses.getUniqueValue(), 

            unread: true 

        }); 

    } 


    /* 
     * ========================================== 
     * 3. DEADLINE REMINDERS
     * ========================================== 
     */ 

    var events = new GlideRecord( 
        'x_snc_campus_con_0_events' 
    ); 

    events.addQuery( 
        'verification_status', 
        'verified' 
    ); 

    events.addNotNullQuery( 
        'registration_deadline' 
    ); 

    events.orderBy( 
        'registration_deadline' 
    ); 

    events.query(); 


    var today = 
        new GlideDateTime(); 


    while (events.next()) { 

        var deadline = 
            new GlideDateTime( 
                events.getValue( 
                    'registration_deadline' 
                ) 
            ); 


        if (!deadline.after(today)) { 

            continue; 

        } 


        var difference = 
            GlideDateTime.subtract( 
                today, 
                deadline 
            ); 


        var milliseconds = 
            Math.abs( 
                difference.getNumericValue() 
            ); 


        var days = 
            Math.floor( 
                milliseconds / 
                (1000 * 60 * 60 * 24) 
            ); 


        if (days <= 7) { 

            data.notifications.push({ 

                type: 'deadline', 

                icon: '⏰', 

                title: 'Deadline Reminder', 

                message: 
                    'Event registration deadline is approaching.', 

                details: 
                    events.getDisplayValue( 
                        'event_name' 
                    ), 

                created_on: 
                    events.getDisplayValue( 
                        'registration_deadline' 
                    ), 

                record_id: 
                    events.getUniqueValue(), 

                notification_id: 
                    'deadline_' + 
                    events.getUniqueValue(), 

                unread: true 

            }); 

        } 

    } 


    /* 
     * ========================================== 
     * 4. EVENT REGISTRATION SUCCESS
     * ========================================== 
     */ 

    var registrations = new GlideRecord( 
        'x_snc_campus_con_0_registrations' 
    ); 

    registrations.addQuery( 
        'student', 
        currentUser 
    ); 

    registrations.orderByDesc( 
        'sys_created_on' 
    ); 

    registrations.query(); 


    while (registrations.next()) { 

        var registeredEventName = ''; 

        if (!registrations.event.nil()) { 

            registeredEventName = 
                registrations.event.getDisplayValue(); 

        } 


        data.notifications.push({ 

            type: 'registration_success', 

            icon: '🎉', 

            title: 'Registration Successful', 

            message: 
                'You have successfully registered for the event.', 

            details: registeredEventName, 

            created_on: 
                registrations.getDisplayValue( 
                    'sys_created_on' 
                ), 

            record_id: 
                registrations.getUniqueValue(), 

            notification_id: 
                'registration_success_' + 
                registrations.getUniqueValue(), 

            unread: true 

        }); 

    } 


    /* 
     * ========================================== 
     * 5. SORT NOTIFICATIONS
     * ========================================== 
     */ 

    data.notifications.sort( 
        function(a, b) { 

            if ( 
                a.created_on < 
                b.created_on 
            ) { 

                return 1; 

            } 

            if ( 
                a.created_on > 
                b.created_on 
            ) { 

                return -1; 

            } 

            return 0; 

        } 
    ); 


    /* 
     * ========================================== 
     * 6. CURRENT COUNT
     * ========================================== 
     */ 

    data.unread_count = 
        data.notifications.length; 


})();
